        return 0
    except (OSError, UnicodeError) as exc:
        _discard_stdout()
        sys.stderr.write("pennywise: cannot write output: %s\n" % exc)
        return 2
    return 0
"""Ledger model, parser and aggregation helpers (standard library only)."""

from __future__ import annotations

import datetime
import decimal
import re
from dataclasses import dataclass
from decimal import Decimal
from typing import Dict, Iterable, List, Optional

_DATE_RE = re.compile(r"\d{4}-\d{2}-\d{2}", re.ASCII)
_AMOUNT_RE = re.compile(r"[+-]?\d+(\.\d{1,2})?", re.ASCII)
_LINE_BREAK_RE = re.compile(r"\r\n|\n|\r")
_FIELD_SEP_RE = re.compile(r"[ \t]+")
_CENT = Decimal("0.01")


class ParseError(ValueError):
    """A line of the ledger is malformed. ``line`` is 1-based."""

    def __init__(self, line: int, reason: str) -> None:
        super().__init__("line %d: %s" % (line, reason))
        self.line = line
        self.reason = reason


@dataclass(frozen=True)
class Entry:
    date: datetime.date
    category: str
    amount: Decimal
    note: str


def parse_date(text: str) -> datetime.date:
    """Parse ``YYYY-MM-DD`` strictly; raise ValueError when malformed or not a real date."""
    if not _DATE_RE.fullmatch(text):
        raise ValueError("invalid date %r (expected YYYY-MM-DD)" % text)
    try:
        return datetime.date(int(text[:4]), int(text[5:7]), int(text[8:10]))
    except ValueError:
        raise ValueError("invalid date %r (no such day)" % text) from None


def _parse_line(number: int, line: str) -> Optional[Entry]:
    stripped = line.strip()
    if not stripped or stripped.startswith("#"):
        return None
    fields = _FIELD_SEP_RE.split(line.lstrip(" \t"), 3)
    if len(fields) < 3:
        raise ParseError(number, "expected DATE CATEGORY AMOUNT [NOTE]")
    date_text, category, amount_text = fields[0], fields[1], fields[2]
    note = fields[3].strip() if len(fields) == 4 else ""
    try:
        date = parse_date(date_text)
    except ValueError as exc:
        raise ParseError(number, str(exc)) from None
    if not _AMOUNT_RE.fullmatch(amount_text):
        raise ParseError(
            number, "invalid amount %r (at most two decimals, no separators)" % amount_text
        )
    return Entry(date, category.lower(), Decimal(amount_text), note)


def parse(text: str) -> List[Entry]:
    """Parse ledger text into entries, in file order. Raises ParseError."""
    if text.startswith("﻿"):
        text = text[1:]
    entries = []
    for number, line in enumerate(_LINE_BREAK_RE.split(text), 1):
        entry = _parse_line(number, line)
        if entry is not None:
            entries.append(entry)
    return entries


def _precision(values: List[Decimal]) -> int:
    widest = max((len(v.as_tuple().digits) for v in values), default=0)
    return max(decimal.DefaultContext.prec, widest + len(str(len(values))) + 5)


def _total(values: Iterable[Decimal]) -> Decimal:
    values = list(values)
    with decimal.localcontext() as ctx:
        ctx.prec = _precision(values)
        total = Decimal(0)
        for value in values:
            total += value
        return total


def balance(entries: Iterable[Entry]) -> Decimal:
    return _total(e.amount for e in entries)


def _group(entries: Iterable[Entry], key) -> Dict[str, Decimal]:
    groups = {}  # type: Dict[str, List[Decimal]]
    for entry in entries:
        groups.setdefault(key(entry), []).append(entry.amount)
    return {name: _total(values) for name, values in groups.items()}


def by_category(entries: Iterable[Entry]) -> Dict[str, Decimal]:
    return _group(entries, lambda e: e.category)


def by_month(entries: Iterable[Entry]) -> Dict[str, Decimal]:
    return _group(entries, lambda e: "%04d-%02d" % (e.date.year, e.date.month))


def filter_entries(
    entries: Iterable[Entry],
    category: Optional[str] = None,
    since: Optional[datetime.date] = None,
    until: Optional[datetime.date] = None,
) -> List[Entry]:
    wanted = category.lower() if category is not None else None
    return [
        e
        for e in entries
        if (wanted is None or e.category == wanted)
        and (since is None or e.date >= since)
        and (until is None or e.date <= until)
    ]


def format_amount(amount: Decimal) -> str:
    """Two decimals, never exponent notation, never negative zero."""
    with decimal.localcontext() as ctx:
        ctx.prec = _precision([amount]) + 2
        quantized = amount.quantize(_CENT)
        if quantized == 0:
            quantized = abs(quantized)
        return format(quantized, "f")


def format_entry(entry: Entry) -> str:
    """``DATE CATEGORY AMOUNT NOTE`` with single spaces; no trailing space without a note."""
    line = "%s %s %s" % (entry.date.isoformat(), entry.category, format_amount(entry.amount))
    return line + " " + entry.note if entry.note else line
