    ParseError,
    balance,
    by_category,
    by_month,
    filter_entries,
    format_amount,
    format_entry,
    parse,
    parse_date,
)

_VALUE_OPTIONS = ("--by", "--category", "--since", "--until", "--format")
_LINE_BREAKS = re.compile(r"[\r\n]")


class _Failure(Exception):
    def __init__(self, status: int, message: str) -> None:
        super().__init__(message)
        self.status = status


