    try:
        return parse_date(text)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(str(exc)) from None


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="pennywise",
        description="Read a plain-text household ledger and tell me where the money went.",
        allow_abbrev=False,
    )
    sub = parser.add_subparsers(dest="command", metavar="COMMAND", required=True)

    def command(name, help_text):
        p = sub.add_parser(name, help=help_text, allow_abbrev=False)
        return p

    p = command("balance", "print the total of all amounts")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = command("summary", "print totals per category or month")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--by", choices=("category", "month"), default="category")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = command("list", "print entries, oldest first")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--category", help="only this category (case-insensitive)")
    p.add_argument("--since", type=_date_arg, metavar="DATE", help="first day included")
    p.add_argument("--until", type=_date_arg, metavar="DATE", help="last day included")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = command("add", "append an entry to FILE")
    p.add_argument("file", metavar="FILE")
    p.add_argument("date", metavar="DATE")
    p.add_argument("category", metavar="CATEGORY")
    p.add_argument("amount", metavar="AMOUNT")
    p.add_argument("note", metavar="NOTE", nargs="?", default="")

    p = command("export", "print entries as CSV")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--format", choices=("csv",), default="csv")
    return parser


def _prepare(argv: List[str]) -> List[str]:
    """Let values that start with a dash be values, not unknown options."""
    out = []
    i = 0
    command = None
    while i < len(argv):
        token = argv[i]
        if command is None:
            out.append(token)
            if not token.startswith("-"):
                command = token
                if command == "add" and argv[i + 1 : i + 2] not in ([], ["-h"], ["--help"]):
                    if "--" not in argv[i + 1 :]:
                        out.append("--")
            i += 1
        elif token in _VALUE_OPTIONS and i + 1 < len(argv):
            out.append(token + "=" + argv[i + 1])
            i += 2
        else:
            out.append(token)
            i += 1
    return out


def _read_ledger(path: str):
    try:
        if path == "-":
            data = sys.stdin.buffer.read()
        else:
            with open(path, "rb") as handle:
                data = handle.read()
        text = data.decode("utf-8")
    except (OSError, UnicodeError) as exc:
        reason = exc.strerror if isinstance(exc, OSError) and exc.strerror else str(exc)
        raise _Failure(2, "cannot read %s: %s" % (path if path != "-" else "standard input", reason))
    try:
        return parse(text)
    except ParseError as exc:
        raise _Failure(1, str(exc))


def _dump(obj) -> str:
    return json.dumps(obj) + "\n"


def _cmd_balance(args) -> str:
    total = format_amount(balance(_read_ledger(args.file)))
    return _dump({"balance": total}) if args.json else total + "\n"


def _cmd_summary(args) -> str:
    entries = _read_ledger(args.file)
    totals = (by_month if args.by == "month" else by_category)(entries)
    rows = [(name, format_amount(totals[name])) for name in sorted(totals)]
    if args.json:
        return _dump(dict(rows))
    return "".join("%s  %s\n" % row for row in rows)


def _listed(args):
    entries = _read_ledger(args.file)
    if args.command == "list":
        entries = filter_entries(entries, args.category, args.since, args.until)
    return sorted(entries, key=lambda e: e.date)


def _cmd_list(args) -> str:
    entries = _listed(args)
    if args.json:
        return _dump(
            [
                {
                    "date": e.date.isoformat(),
                    "category": e.category,
                    "amount": format_amount(e.amount),
                    "note": e.note,
                }
                for e in entries
            ]
        )
    return "".join(format_entry(e) + "\n" for e in entries)


def _cmd_export(args) -> str:
    entries = _listed(args)
    buffer = io.StringIO()
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in entries:
        writer.writerow([e.date.isoformat(), e.category, format_amount(e.amount), e.note])
    return buffer.getvalue()


def _cmd_add(args) -> str:
    if args.file == "-":
        raise _Failure(2, "add does not accept - as FILE")
    for name, value in (("date", args.date), ("category", args.category), ("amount", args.amount)):
        if not value or re.search(r"\s", value):
            raise _Failure(1, "invalid entry: %s %r must be one word" % (name, value))
    if _LINE_BREAKS.search(args.note):
        raise _Failure(1, "invalid entry: note must not contain a line break")
    line = "%s %s %s" % (args.date, args.category, args.amount)
    if args.note.strip():
        line += " " + args.note
    try:
        (entry,) = parse(line)
        text = format_entry(entry)
        payload = (text + "\n").encode("utf-8")
    except ParseError as exc:
        raise _Failure(1, "invalid entry: %s" % exc.reason)
    except UnicodeError:
        raise _Failure(1, "invalid entry: not valid UTF-8 text")
    try:
        prefix = b""
        if os.path.exists(args.file) and os.path.getsize(args.file) > 0:
            with open(args.file, "rb") as handle:
                handle.seek(-1, os.SEEK_END)
                if handle.read(1) not in (b"\n", b"\r"):
                    prefix = b"\n"
        with open(args.file, "ab") as handle:
            handle.write(prefix + payload)
    except OSError as exc:
        raise _Failure(2, "cannot write %s: %s" % (args.file, exc.strerror or exc))
    return text + "\n"


_COMMANDS = {
    "balance": _cmd_balance,
    "summary": _cmd_summary,
    "list": _cmd_list,
    "add": _cmd_add,
    "export": _cmd_export,
}


def _discard_stdout() -> None:
    """Point stdout at /dev/null so the interpreter's final flush cannot fail again."""
    try:
        os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def main(argv: Optional[List[str]] = None) -> int:
    argv = list(sys.argv[1:] if argv is None else argv)
    try:
        args = _build_parser().parse_args(_prepare(argv))
    except SystemExit as exc:
        return exc.code if isinstance(exc.code, int) else 2
    try:
        output = _COMMANDS[args.command](args)
    except _Failure as failure:
        sys.stderr.write("pennywise: %s\n" % failure)
        return failure.status
    try:
        sys.stdout.write(output)
        sys.stdout.flush()
    except BrokenPipeError:
        _discard_stdout()
        return 0
    except (OSError, UnicodeError) as exc:
        _discard_stdout()
        sys.stderr.write("pennywise: cannot write output: %s\n" % exc)
        return 2
    return 0
